import numpy as np
import pandas as pd
from solver import Algorithm
from typing import Tuple, List


class Evolved(Algorithm):
    """
    Serial character-Trie prefix caching optimizer.

    Candidates (all built from shared serialized cell strings):
      (A) global frequency-ranked order: sum(len(v)*cnt*(cnt-1));
      (C) original column order;
      (H) size-budgeted hill-climb on unit relocations, scored with the
          exact Trie objective;
      (B1) conditional partition tree, pair-repetition splits, best global tail;
      (B2) conditional partition tree, immediate-savings splits with
           group-local frequency tails.
    Each candidate is scored exactly once with the exact ideal Trie reuse
    (dedup-weighted sum of adjacent LCPs of sorted unique strings, computed
    via binary-search prefix-slice equality so comparisons run in C).
    The best candidate is returned; no cell values, rows or columns altered.
    """

    def _serialize_columns(self, df: pd.DataFrame, cols: List[str]):
        """Return dict col -> object array of serialized cell strings ('' for NA)."""
        ser = {}
        for c in cols:
            s = df[c]
            arr = s.astype(str).values.astype(object)
            na = s.isna().values
            if na.any():
                arr = arr.copy()
                arr[na] = ""
            ser[c] = arr
        return ser

    def _lcp(self, a: str, b: str) -> int:
        """Longest common prefix via binary search on prefix slices (C speed)."""
        if a == b:
            return len(a)
        lo, hi = 0, min(len(a), len(b))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    def _trie_score(self, strs: List[str]) -> int:
        """Exact ideal Trie reuse.

        Duplicate rows are adjacent after sorting and share their full
        length, so deduplicate and add len*(cnt-1) per unique string, then
        sum adjacent LCPs over the sorted unique strings.
        """
        if len(strs) < 2:
            return 0
        cnt = {}
        for s in strs:
            cnt[s] = cnt.get(s, 0) + 1
        tot = 0
        for s, c in cnt.items():
            if c > 1:
                tot += len(s) * (c - 1)
        uniq = sorted(cnt)
        lcp = self._lcp
        prev = uniq[0]
        for cur in uniq[1:]:
            tot += lcp(prev, cur)
            prev = cur
        return tot

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        n, m = df.shape
        cols = list(df.columns)

        if n == 0 or m == 0:
            orders = [list(cols) for _ in range(n)]
            return df.copy().astype(object), orders

        # ---- col_merge: grouped columns stay adjacent as ordering units ----
        merged = {}
        for group in (col_merge or []):
            g = [c for c in group if c in cols]
            for c in g:
                merged[c] = g
        units = []
        seen = set()
        for c in cols:
            if c in merged and c not in seen:
                g = [x for x in merged[c] if x in cols and x not in seen]
                units.append(g)
                seen.update(g)
            elif c not in seen:
                units.append([c])
                seen.add(c)
        unit_key = {id(u): i for i, u in enumerate(units)}

        # ---- shared serialization + factorization ----
        ser = self._serialize_columns(df, cols)
        scores = {}
        codes = {}
        codelen = {}
        for c in cols:
            arr = ser[c]
            uniq, inv = np.unique(arr, return_inverse=True)
            cnt = np.bincount(inv, minlength=len(uniq))
            lens = np.fromiter((len(x) for x in uniq), dtype=np.int64, count=len(uniq))
            scores[c] = int((lens * cnt * (cnt - 1)).sum())
            codes[c] = inv
            codelen[c] = lens

        def serialize_global(col_order):
            return ["".join(t) for t in zip(*[ser[c] for c in col_order])]

        def serialize_rows(row_orders):
            out = []
            for r in range(n):
                o = row_orders[r]
                out.append("".join([ser[c][r] for c in o]))
            return out

        # ---- candidates A (frequency-ranked) and C (original) ----
        unit_freq = {id(u): sum(scores[c] for c in u) for u in units}
        order_A_units = sorted(units, key=lambda u: (-unit_freq[id(u)], unit_key[id(u)]))
        global_order = [c for u in order_A_units for c in u]
        order_C = list(cols)

        scA = self._trie_score(serialize_global(global_order))
        scC = self._trie_score(serialize_global(order_C))
        if scA >= scC:
            tail_order, best_global = global_order, scA
        else:
            tail_order, best_global = order_C, scC

        # ---- candidate H: size-budgeted hill-climb on the exact objective ----
        hill_order, scH = None, -1
        k = len(units)
        if 3 <= k <= 40 and n <= 120_000:
            # adapt evaluation budget so total hill-climb cost stays bounded
            max_evals = int(max(15, min(120, 1_200_000 // max(n, 1))))
            cur_units = list(order_A_units)
            cur_score = best_global

            def serialize_units(u_list):
                return serialize_global([c for u in u_list for c in u])

            evals = 0
            improved = True
            while improved and evals < max_evals:
                improved = False
                best_gain, best_move = 0, None
                for i in range(k):
                    u = cur_units[i]
                    rest = cur_units[:i] + cur_units[i + 1:]
                    for j in range(k):
                        if j == i:
                            continue
                        cand = rest[:j] + [u] + rest[j:]
                        evals += 1
                        sc = self._trie_score(serialize_units(cand))
                        if sc - cur_score > best_gain:
                            best_gain, best_move = sc - cur_score, cand
                        if evals >= max_evals:
                            break
                    if evals >= max_evals:
                        break
                if best_move is not None:
                    cur_units = best_move
                    cur_score += best_gain
                    improved = True
            hill_order = [c for u in cur_units for c in u]
            scH = self._trie_score(serialize_global(hill_order))

        if scH > best_global:
            tail_order, best_global = hill_order, scH

        # ---- bounded conditional partition trees ----
        depth_cap = 10 if col_stop is None else max(1, min(int(col_stop), 10))
        max_split_candidates = 12
        col_pos = {c: i for i, c in enumerate(cols)}
        all_rows = np.arange(n)
        local_tail_max_rows = 20000
        local_tail_max_cols = 60

        def build_tree(split_mode, local_tail):
            order_arr = np.empty((n, m), dtype=object)

            def local_order(rows, remaining):
                if (len(rows) > local_tail_max_rows
                        or len(remaining) > local_tail_max_cols):
                    return [c for c in tail_order if c in remaining]
                loc = {}
                for c in remaining:
                    nb = np.bincount(codes[c][rows], minlength=len(codelen[c]))
                    loc[c] = int((codelen[c] * (nb - 1).clip(0)).sum())
                return sorted(remaining, key=lambda c: (-loc[c], col_pos[c]))

            def build(rows, remaining, pos, depth):
                if pos >= m or len(rows) == 0 or not remaining:
                    return
                if len(rows) < 2 or depth >= depth_cap:
                    tl = local_order(rows, remaining) if local_tail else \
                        [c for c in tail_order if c in remaining]
                    for r in rows:
                        order_arr[r, pos:pos + len(tl)] = tl
                    return
                if len(remaining) <= 25:
                    cands = remaining
                else:
                    cands = sorted(remaining, key=lambda c: (-scores[c], col_pos[c]))[:max_split_candidates]
                best, best_sc = None, -1
                for c in cands:
                    nb = np.bincount(codes[c][rows], minlength=len(codelen[c]))
                    if split_mode == "pair":
                        sc = int((codelen[c] * nb * (nb - 1)).sum())
                    else:
                        sc = int((codelen[c] * (nb - 1).clip(0)).sum())
                    if sc > best_sc:
                        best_sc, best = sc, c
                if best is None or best_sc <= 0:
                    tl = local_order(rows, remaining) if local_tail else \
                        [c for c in tail_order if c in remaining]
                    for r in rows:
                        order_arr[r, pos:pos + len(tl)] = tl
                    return
                for r in rows:
                    order_arr[r, pos] = best
                rest = [c for c in remaining if c != best]
                if not rest:
                    return
                cd = codes[best][rows]
                for v in np.unique(cd):
                    build(rows[cd == v], rest, pos + 1, depth + 1)

            build(all_rows, list(cols), 0, 0)
            return [list(order_arr[r]) for r in range(n)]

        candidates = [(best_global, [list(tail_order) for _ in range(n)])]

        tree1 = build_tree("pair", False)
        candidates.append((self._trie_score(serialize_rows(tree1)), tree1))

        tree2 = build_tree("imm", True)
        candidates.append((self._trie_score(serialize_rows(tree2)), tree2))

        orders = max(candidates, key=lambda t: t[0])[1]

        # ---- materialize output preserving every value ----
        colidx = {c: i for i, c in enumerate(cols)}
        vals = df.to_numpy(dtype=object) if m else np.empty((n, 0), dtype=object)
        out = np.empty((n, m), dtype=object)
        for r in range(n):
            vrow = vals[r]
            out[r] = [vrow[colidx[c]] for c in orders[r]]

        result = pd.DataFrame(out, columns=cols, index=df.index).astype(object)
        return result, orders
